    &#039;Authorization&#039;: &#039;my-auth-token&#039;
  })
};

// Exemplo de uso em uma requisição POST
this.http.post&lt;any&gt;(url, data, httpOptions)

JavascriptTypescript/Angular/Roteamento.content:
Roteamento
2025-11-23
tags: index Angular
Entendendo arquivo de rotas
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula23.md ]

ng new projectName
→ Isso é feito para criar um novo projeto angular, Aula1, se aceitar criar as rotas, ele cria um arquivo de routes.module que deve ser configurado devidamente para o routing da sua aplicação

Enfim, como dito na seção anterior brevemente, o Routes e o RoutesModule são duas figuras do @angular/router que lidam com as rotas no angular, você pode definir como parâmetro no @NgModule() que você vai usar esses modulos e exportar para toda a aplicação:
import { NgModule } from &#039;@angular/core&#039;;
import { RouterModule, Routes } from &#039;@angular/router&#039;;

const routes :Routes = [
	{ path: &quot;&quot;,component: someComponent, pathMatch: &#039;full&#039; },
	{ path: &quot;otherComponent&quot;,component: otherComponent }
]

@NgModules({
	imports: [RouterModule.forRoot(routes)],
	exports: [RouterModule]
})

O router full é para ele seguir com o processamento padrão de routes em rotas raiz, dessa forma, o roteamento via front-end fica bem enxuto em casos de realizar todo o back no front-end.
Esse arquivo de rotas é criado usando o ng new
Rota Coringa e redirectTo
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula23.md ]
podemos definir o path como ” ** ” (sem os espaços) e usar, ao invés do component, o redirectTo: &#039;path&#039; para redirecionar para o path, entendendo que o path vai ser igual aos outros paths nos objetos, sem o / no começo
import { NgModule } from &#039;@angular/core&#039;;
import { RouterModule, Routes } from &#039;@angular/router&#039;;

const routes :Routes = [
	{ path: &quot;&quot;,component: someComponent, pathMatch: &#039;full&#039; },
	{ path: &quot;otherComponent&quot;,component: otherComponent },
	{ path: &#039;**&#039;, component: NotFoundComponent } // Rota Coringa
]

@NgModules({
	imports: [RouterModule.forRoot(routes)],
	exports: [RouterModule]
})

Navegação entre páginas
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula23.md ]
A forma padrão, e pior, usando apenas html puro, ficaria assim:
→ A do angular é melhor, desse demora muito
!
Bom, a forma do angular possuí diversas vantagens, uma delas é poder usar rotas parametrizadas, vamos nos aprofundar disso mais a frente mas a ideia é que você usa [‘path’, 1] e ela sai → path/1 e o legal é que podemos depois transformar isso num array, juntar arrays, pegar os valores e etc… Além de ser muuuito mais rápido, não esquece que o routerLink tem que estar com [].
&lt;header&gt;
	&lt;h1&gt;Testing Routes&lt;/h1&gt;
	&lt;ul&gt;
			&lt;li&gt; &lt;a routerLink=&quot;/&quot; &gt;Home&lt;/a&gt; &lt;/li&gt;
			&lt;li&gt; &lt;a [routerLink]=&quot;[&#039;/about&#039;]&quot; &gt;about&lt;/a&gt; &lt;/li&gt;
			&lt;li&gt; &lt;a routerLink=&quot;/404&quot; &gt;404&lt;/a&gt; &lt;/li&gt;
	&lt;/ul&gt;
&lt;/header&gt;
Active Routes
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula24.md ]
Podemos colocar uma classe css em uma rota que está ativa, o angular fornece isso de uma forma bem fácil e completa, só usar esse atributo html:

[routerLinkActive] = ”[‘class’]”
→ sendo class uma classe css

Quando você usar isso, vai perceber que ele usa por padrão um padrão cascata, então quando você tiver em /alguma coisa, ele vai colocar a classe tanto na rota “home”, a /, quanto na rota alguma coisa. Portanto, precisamos colocar uma outra propriedade:

[routerLinkActiveOptions]=“{exact: true}“

Parâmetros nas rotas
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula24.md ]
Para parametrizar as rotas, usamos :param, exemplo:
{ path: &quot;about/:username/:id&quot;,component: someParameterComponent },
Perceba que ao fazer isso, perdemos a rota simples about, ela agora deve sempre passar um username e um id, exemplo: about/kkphoenix/1
E para podermos usar essas informações, devemos fazer uso do ActivatedRoute:
import { ActivatedRoute } from &#039;@angular/router&#039; 

class someParameterComponent implements OnInit{
	constructor(
		private activatedRoute :ActivatedRoute
	){}

	ngOnInit() :void{

		this.activatedRout.params.subscribe(
			res =&gt; { console.log( {res.username, res.id} ) }
		)
	}

}
Além disso, para podermos pegar os parametros colocados depois do ?, que são os queryParams, devemos fazer:
this.activatedRout.queryParams.subscribe(
	res =&gt; { console.log( res ) }
)
Redirecionamento com ts
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula25.md ]
Temos como redirecionar pelo controller também, basta usarmos o objeto Router:
import {Router} from &quot;@angular-core/router&quot;

class someComponent implements OnInit{

	/* 
		Isso vai navegar para somePage, 
		é igual as rotas por routeLink
  */
	private navigateTo :Array&lt;string&gt; = [&#039;somePage&#039;] 

	constructor( private router :Router ){}

	ngOnInit() :void{

		setInterval( ()=&gt;{ 
			// Rapido:
			this.router.navigate(this.navigateTo);

			// NavigateByUrl faz reload da tela:
			// this.router.navigateByUrl(this.navigateTo)

		}, 5000 )

	}

}
Rotas filhas
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula25.md ]
Para criamos rotas filhas, vamos ir lá no routing.module para adicionar, no nosso objeto da rota pai, um atributo chamado children: [], que recebe um array de objetos, objetos que são também objetos de rota:
import { NgModule } from &#039;@angular/core&#039;;
import { RouterModule, Routes } from &#039;@angular/router&#039;;

const routes :Routes = [
	{ path: &quot;&quot;,component: someComponent, pathMatch: &#039;full&#039; },
	{ path: &quot;otherComponent&quot;,component: otherComponent, 
		children:[
			{path: &#039;:username/:id&#039;, component: otherComponent}
		] 
	}
]

@NgModules({
	imports: [RouterModule.forRoot(routes)],
	exports: [RouterModule]
})

Observe que colocamos o mesmo componente, o otherComponent para essa rota pai, contudo, poderíamos colocar outro componente… Além disso, não colocamos o primeiro path, vamos navegar para: otherComponent/:username/:id mas não colocamos o path do pai pois ele já será adicionado
Além disso, sobre o active routes que fizemos na aula anterior, a rota pai ficará ativa
Lazy Loading
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula25.md ]
Lazy loading é um carregamento de módulos, você carrega somente o módulo que o usuário está entrando, para isso, obviamente precisamos criar um módulo e o component do módulo, contudo, isso torna tudo muito mais simples:

ng g m path
ng g c path

Interessante dizer que se você coloca a linha de export de componente, ele vai ter que carregar a exportação também, então se você acha que não vai usar essa funcionalidade, você retira a linha, é uma ótima sacada para ter em mente.
E vamos aos conceitos, na rota root, usamos o forRoot para carregar as rotas:
!
No caso de uma rota filha, você usa forChild(routes) no lugar do forRoot(routes) no componente filho. Além disso, no componente pai, devemos importar, literalmente, o módulo:
import { NgModule } from &#039;@angular/core&#039;;
import { RouterModule, Routes } from &#039;@angular/router&#039;;

const routes :Routes = [
	{ path: &quot;&quot;,component: someComponent, pathMatch: &#039;full&#039; },
	{ 
		path: &quot;otherComponent&quot;,
		loadChildren: () =&gt; import(&#039;./pages/pages.module&#039;).then( 
			pages =&gt; pages.PagesModule;
		)
	}
]

@NgModules({
	imports: [RouterModule.forRoot(routes)],
	exports: [RouterModule]
})
Lembre-se que o RoutingModule do próprio modulo filho deve estar importado  nas configurações desse módulo filho:
!
Estratégia com useHash
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 12/Aula25.md ]
Essa aula é só para mostrar em aberto mesmo uma função do angular que se você quiser se aprofundar, você pode, tem como criar aquelas rotas antigas com # também no angular, é só colocar { useHash: true } na chamada de forRoot, como parâmetro:
!
E aí a rota vai ficar:  localhost:4200/#/

JavascriptTypescript/Angular/Servicos-e-.content:
Serviços e Injeção de Dependência
2025-11-23
tags: index Angular
Insight eventBinding, SERVICES, Comunicação e arquitetura com services
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/Section 9/Aula17.md ]
Tem como colocar qualquer evento no event binding, ou seja, inclusive um  keyup.enter…
UUUUUUUU, não fazia ideia que no angular existia algo assim, nossa, isso é muito bom… O service serve justamente para criar serviços, arquivos de comunicação, encapsulamento de tarefas e injeção de dependências, se você não sabe a definição do que eu falei, recomendo ler Arquitetura Limpa e pesquisar sobre os conceitos. Podemos gerar um arquivo service criando um:

ng g s (path)
ng generate service (path)

Sendo path o caminho e por padrão o path que você está, geralmente usado service/servicename. Ao criar o seu service, para importa-lo em qualquer outro lugar da sua aplicação, é só importar como se fosse um método de classe mesmo…
// Service file (arquivo service)
import { Injectable } from &#039;@angular/core&#039;;

@Injectable({
  providedIn: &#039;root&#039;
})

export class TestingServiceService {
  private _message = &#039;working&#039;

  constructor() {}
  
  // ----------- getters and setters -----------
  get message() { return this.message }

}
O @Injectable diz para o Angular que essa classe é uma classe injetável como dependência em outras classes, e como colocamos providedIn: &#039;root&#039;, está disponível na root do projeto, em sua pasta inicial…
import { Component, OnInit } from &#039;@angular/core&#039;;
import { TestingServiceService } from &#039;./services/testing-service.service&#039;;

@Component({
  selector: &#039;app-root&#039;,
  template: `
	`
})
export class AppComponent implements OnInit {

	constructor( public testingService :TestingServiceService){}

  ngOnInit(): void {
    console.log(this.testingService.message);
  }

}
Podemos mudar dados em um service e colher os dados do service aplicando em algum lugar, assim, ambos componentes dependem do service e não se comunicam, criando uma perfeita injeção de dependência
a → service ← b
O subscribe do angular é um addEventListener de um componente… Ele fica escutando quando um Emitter, uma instância de EventEmitter cria um emit() de algum evento
Code Exemple
// Service file (arquivo service)
import { Injectable, EventEmitter } from &#039;@angular/core&#039;;

@Injectable({
  providedIn: &#039;root&#039;
})

export class TestingServiceService {
  public emitter = new EventEmitter()
	 
  constructor() {}

	buttonClick(message :string){
		this.emitter.emit(message)
	}
}
// file: component.ts
import { Component, OnInit } from &#039;@angular/core&#039;;
import { TestingServiceService } from &#039;./services/testing-service.service&#039;;

@Component({
  selector: &#039;app-root&#039;,
  template: `
	`
})
export class AppComponent implements OnInit {

	constructor( public testingService :TestingServiceService){}

  ngOnInit(): void {
    this.testingService.emitter.subscribe({
			next : (res) =&gt; console.log(res),
			error: (err) =&gt; console.log(err),
		});
  }

}
Bom, a aula foi sobre como simular um servidor com uma lib npm chamada: json-server. Basicamente só precisa criar um arquivo chamado db.json com o seguinte formato:

npm install -g json-server
json-server —watch db.json

JavascriptTypescript/Angular/Testes.content:
Testes
2025-11-23
tags: index Angular
Introdução ao Jasmine, Estrutura base
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula29.md ]
Um teste unitário é diferente de um teste de fluxo. Um teste de fluxo verifica as saídas e os envios de página. Em contrapartida, os testes unitários verificam uma unidade da aplicação como um todo. Para realizar os testes unitários, utilizamos o Karma para node e o Jasmine para o angular.
Estrutura base
import { TestBed } from &#039;@angular/core/testing&#039;;
import { ComponentName } from &#039;./ComponentName&#039;;

describe(&#039;ComponentName&#039;, () =&gt; { 

    let component :ComponentName;
    let fixture :ComponentFixture&lt;ComponentName&gt;

    // ----- Estrutura do tipo de teste -----
    // Block

    // ----- Teste primário -----
    beforeEach( ()=&gt;{
        fixture = TestBed.createComponent(ComponentName);
        component = fixture.componentInstance;

        fixture.detectChanges();
    })

    // ----- its -------

});
Via de regra, se segue essa estrutura adicionando partes de acordo com o que você precisa testar. Nas seções “Dos Testes x”, poderemos ver essas estruturas.
Entendendo a sintaxe

describe(component, callBack): Os testes que ocorrerão no component por meio do callBack;
it(&#039;description&#039;, callback): Isso deveria &lt;descrição&gt;. Exemplo: it(&#039;O AppComponent deveria ser criado&#039;, ...)
TestBed: Uma classe que fornece um ambiente de teste para o código que está sendo testado.
fixture: Usado para interagir com o componente criado e com seu template. Não é uma instância, é a interface do componente.

Manipulando testes fluentemente
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula30.md ]

expect(x): Diz que é esperado que x aconteça.
x.toEqual(y): Espera que x seja igual a y.
x.not.y: Transforma a asserção y em negativa. Ex: expect(sum).not.toEqual(3) vai dar erro quando o resultado for 3.

Melhorando a cobertura de testes
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula31.md ]

ng test —code-coverage

Faz a cobertura do código para ver se todos os ifs, as funções e outros foram testados.
Under Test; Estrutura para U
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula32.md ]

beforeEach: antes de todas as specs (testes it), execute isso.
fixture.detectChanges: detecta as mudanças da fixture.
x.toBeTruthy: espera que x seja true.

Existe uma convenção para como as mensagens do it devem ser criadas, o (U) será como Under Test (em teste) e definirá a função ou o callback que está sendo testado.
Dos Testes Unitários (U)
Na estrutura dos testes unitários, adicione em // block a estrutura para definir os componentes:
beforeEach(async () =&gt; {
	await TestBed.configureTestingModule({
		declarations: [Component1, Component2]
	}).compileComponents();
})
Testando interfaces; Estrutura de teste para I
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula33.md ]
U → Under Test;
I → Interface’s test
fixture.debugElement.nativeElement.querySelector(&#039;cssSelector&#039;)
Isso permite você ter um elemento. Contudo, quando você definir elementos, executar funções, todos os estados dos objetos não vão ser atualizados como quer. Dessa forma, você deve detectar mudanças com fixture.detectChanges.
Estrutura describe para U; Manipulação de testes
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula34.md ]

x.trim(): Retira os espaços vazios da frente e de trás do conteúdo de uma string para testes de elementos html.
x.toContain(y): Verifica se existe em x o y. Exemplo: &quot;SomeText&quot; = x, x.toContain(&quot;Text&quot;) → true.
x.toEqual(y): Verifica se x é y. Exemplo: &quot;SomeText&quot; = x, x.toEqual(&quot;Text&quot;) → false; x.toEqual(&quot;SomeText&quot;) → true.

Mock; Estrutura de teste de um service
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula35.md ]
Mockar algo significa substituir ou simular um objeto real ou uma função durante os testes. Para isso, usamos o HttpClientTestingModule e o HttpTestingController.
O HttpClientTestingModule deve ser importado no configureTestingModule.
Testando o serviço - Incremento na estrutura dos testes de service; Arquitetura dos Testes
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula36.md ]
No Jasmine, temos os blocos de preparação, como beforeEach() e describe(). Um importante incremento ao grupo é o afterEach() que será executado ao final de cada it().
O método verify() do httpTestingController verifica se está tudo certo com os requests a um endereço.
afterEach(() =&gt; {
	httpTestingController.verify();
});
As importações nos imports do configureTestingModule não passam as dependências automaticamente, os testes dos dependentes do componente que possui a importação devem ter a importação também.
Teste com mock no serviço
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula37.md ]

of(x) (RxJS): retorna o valor de x, como se fosse um await &lt;method&gt;.
done do it: O done é um parâmetro do callback do it → it(description, callback(done)). Ele encerra um it abruptamente, útil para testes assíncronos.
httpTestingController.expectOne(URL): Recebe a response da URL que você proporcionar e pode ser usada para testes.
req.flush(defaultValue): Muda a response do request.
spyOn(service, &#039;methodName&#039;).and.returnValue(of(mockData)): Espiona um método de um serviço e retorna um valor mockado. É interessante não depender do serviço real para testar.

// sendo defaultValue o mesmo do exemplo anterior e service o service em questão
spyOn(service, &#039;serviceMethodName&#039;).and.returnValue(of(defaultValue))

component.ngOnInit();
fixture.detectChanges();
Uma boa prática nessa estrutura é usar o expect(service.serviceMethod).toHaveBeenCalledWith() para ter certeza que o spyOn, o ngOnInit e o detectChanges estão funcionando junto com o componente.
Teste de Interface com mock no componente 2
[ fonte: /home/kkphoenix/Documents/Programação/JavascriptTypescript/Angular/v16/section14/Aula38.md ]
A mesma coisa que você faz com o spyOn() para o teste unitário, deve ser feito nos testes de interface, para coletar continuamente os dados e verificar a interface.
it(&#039;should list data&#039;, (done)=&gt;{
	spyOn(service, &#039;serviceListMethod&#039;).and.returnValue(of(defaultValue));

	component.ngOnInit();
	fixture.detectChanges();

	expect(service.list).toHaveBeenCalledWith();

	// expects da data...
})

