		&lt;input 
			type=&quot;text&quot; required name=&quot;textInput&quot;
			#textInput = &quot;ngModel&quot; [ngModel]=&quot;textInput.value&quot; 
    &gt;			

		&lt;button type=&quot;submit&quot; [disabled]=&quot;nomeDoSeuFormulario.invalid&quot; &gt; 
			Submit 
		&lt;/button&gt;
