			dir: require(&#039;path&#039;).join(__dirname, &#039;../coverage&#039;),
			reports: [&#039;html&#039;, &#039;lcovonly&#039;],
			fixWebpackSourcePaths: true

		},

		reporters: [&#039;progress&#039;, &#039;kjhtml&#039;],
